sed -i "1s/.*/import {shouldContinueToolLoop, addUsage} from '.\/orchestratorHelpers.js';/" src/orchestration/orchestratorHelpers.test.ts
cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

describe('addUsage', () => {
  const A = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
  const B = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

  it('sums each token field when both sides reported', () => {
    expect(addUsage(A, B)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('keeps the side that reported, and stays undefined when neither did', () => {
    expect(addUsage(undefined, B)).toEqual(B);
    expect(addUsage(A, undefined)).toEqual(A);
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });
});
EOF
cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

export function addUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!total || !round) return total ?? round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
EOF
